import{_ as a,o as s,c as d,ag as i}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"WaitAI 等待模拟量输入","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/4. IO 指令/WaitAI.md","filePath":"3. 指令/4. IO 指令/WaitAI.md","lastUpdated":1778862643000}'),e={name:"3. 指令/4. IO 指令/WaitAI.md"};function r(n,t,o,h,l,p){return s(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="waitai-等待模拟量输入" tabindex="-1">WaitAI 等待模拟量输入 <a class="header-anchor" href="#waitai-等待模拟量输入" aria-label="Permalink to &quot;WaitAI 等待模拟量输入&quot;">​</a></h1><p>模拟量输入等待指令用于在设定时间内，监控指定的模拟量输入（AI）端口值。当该端口的实时数值与给定的目标值相等时，程序继续向下执行。若超过设定时间仍未满足条件，则记录超时状态。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p><code>WaitAI (AIN, VALUE, T, INTERENABLE, RET, [Goto])</code></p><p><code>WaitAI(模拟量输入端口, 目标触发值, 超时时间, 打断使能, 结果变量, [跳转行号])</code></p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>AIN</td><td>AI</td><td>用于等待判断的目标模拟量输入端口</td><td>必填</td></tr><tr><td>VALUE</td><td>real 或 REAL 变量</td><td>期望等待的模拟量数值</td><td>必填</td></tr><tr><td>T</td><td>int 或 INT 变量</td><td>等待限时，单位 ms（0：强制等待直到信号满足）</td><td>必填</td></tr><tr><td>INTERENABLE</td><td>int (0 或 1)</td><td>程序暂停恢复后的计时逻辑（0：继续计时，1：重新计时）</td><td>必填</td></tr><tr><td>RET</td><td>INT 变量</td><td>返回执行结果（0：成功，1：超时）</td><td>必填</td></tr><tr><td>[Goto]</td><td>label</td><td>超时后程序指针跳转到的指定标签名</td><td>可选</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WaitAI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (AI1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, INT1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑描述：</strong></p><p>等待模拟量输入变量 <strong>AI1</strong> 达到 <strong>5.0</strong> 的状态，设定等待时间为 <strong>1000ms</strong>。如果期间程序暂停并恢复，计时器将<strong>重新开始计时</strong>（因为 INTERENABLE 为 1）。若 1000ms 内未等到信号，则变量 <strong>INT1</strong> 被赋值为 <strong>1</strong>，表示等待超时，程序继续向下执行。</p>',15)])])}const g=a(e,[["render",r]]);export{k as __pageData,g as default};
